import json
from httpbin.core import app
client = app.test_client()

def test_post_json_body_reflects_json_field():
    payload = {'alpha': 1, 'beta': 'two'}
    r = client.post('/post',
                    data=json.dumps(payload),
                    content_type='application/json')
    assert r.status_code == 200
    body = r.get_json()
    assert body is not None
    assert body['json'] == {'alpha': 1, 'beta': 'two'}
    assert body['form'] == {}
    assert body['args'] == {}
    assert body['files'] == {}
    assert isinstance(body['data'], str)
    assert '"alpha"' in body['data']
    assert isinstance(body['origin'], str)

test_post_json_body_reflects_json_field()
